WITH p AS (SELECT coalesce(%s::text,'') ma_kh,coalesce(%s::text,'') status,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR(coalesce(u.ds_branchs,'')='' AND coalesce(u.ds_stocks,'')='') unrestricted FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT k.ma_kh,k.ten_kh,k.ten_kh2,k.ten_viet_tat,k.ong_ba,k.dien_thoai,k.e_mail,k.dia_chi,k.ma_nvpt,k.nh_kh1,k.nh_kh2,k.nh_kh3,k.nh_kh4,k.nh_kh5,k.cn_max,k.ma_httt,k.ma_tt,k.status,count(*) OVER() total FROM public.dmkh k CROSS JOIN s WHERE s.ok IS NOT NULL AND(s.ma_kh='' OR k.ma_kh=ANY(string_to_array(s.ma_kh,',')))AND(s.status='' OR k.status::text=ANY(string_to_array(s.status,',')))AND(s.unrestricted OR coalesce(k.ds_ma_dvcs,'')='' OR string_to_array(k.ds_ma_dvcs,',')&&string_to_array(s.bs,',')) ORDER BY k.ma_kh LIMIT(SELECT lim FROM p);
